import Table from '@mui/material/Table';
import TableBody from '@mui/material/TableBody';
import TableCell from '@mui/material/TableCell';
import TableContainer from '@mui/material/TableContainer';
import TableHead from '@mui/material/TableHead';
import TableRow from '@mui/material/TableRow';
import Paper from '@mui/material/Paper';
import { useState, useEffect } from 'react';
import axios from 'axios';
import Button from '@mui/material/Button';
import { Link } from 'react-router-dom'; 

export default function ViewProduct() {
  const [product, setProduct] = useState([]);

  useEffect(() => {
    axios.get("http://localhost:7000/product/getProducts") 
      .then((res) => {
        console.log(res.data.pdata); 
        setProduct(res.data.pdata || []);  
      })
      .catch((error) => {
        console.log(error);
      });
  }, []);

  const HandleDelete = (id) => {
    axios.delete(`http://localhost:7000/product/deleteProduct/${id}`) 
      .then((res) => {
        console.log(res);
        alert("Product deleted"); 
        setProduct(product.filter((item) => item._id !== id));  
      })
      .catch((error) => {
        console.log(error);
      });
  };

  return (
    <div>
      <h2>View Product</h2>
      <TableContainer component={Paper}>
        <Table>

          <TableHead>
            <TableRow>
              <TableCell align="right">Product Name</TableCell>  
              <TableCell align="right">Description</TableCell>
              <TableCell align="right">Price</TableCell>
              <TableCell align="right">Quantity</TableCell>
              <TableCell align="right">CategoryId</TableCell>
              <TableCell align="right">Product Image</TableCell>
              <TableCell align="right">Action</TableCell> 
            </TableRow>
          </TableHead>

          <TableBody>
            {product && product.length > 0 ? (
              product.map((row) => (
                <TableRow key={row._id}>
                  <TableCell align="right">{row.name}</TableCell>  
                  <TableCell align="right">{row.description}</TableCell>
                  <TableCell align="right">{row.price}</TableCell>
                  <TableCell align="right">{row.quantity}</TableCell>
                  <TableCell align="right">{row.categoryId}</TableCell>
                  <TableCell align="right">
                    <img src={`http://localhost:7000/image/${row.productimage}`}
                    alt='' 
                    width="80" />
                  </TableCell>
                  <TableCell align="right">
                    <Button
                      variant='outlined'
                      component={Link}
                      to={`/Admin/UpdateProduct/${row._id}`}  
                    >
                      UPDATE PRODUCT
                    </Button>

                    <Button
                      variant='outlined'
                      onClick={() => HandleDelete(row._id)}
                      style={{ marginLeft: "10px" }}
                    >
                      DELETE
                    </Button>
                  </TableCell>

                </TableRow>
              ))
            ) : (
              <TableRow>
                <TableCell colSpan={6} align="center">
                  No Products Found
                </TableCell>
              </TableRow>
            )}
          </TableBody>

        </Table>
      </TableContainer>
    </div>
  );
}